import { Badge, Tooltip } from '@mantine/core'
import type { ReactNode } from 'react'
import type { DataSource } from '../api/types'

const SOURCES: Record<DataSource, { label: string; color: string; explanation: string }> = {
  measured: {
    label: 'Measured',
    color: 'green',
    explanation:
      'Reported as measured observations by the API. Provenance does not establish statistical significance or a causal effect.',
  },
  simulated: {
    label: 'Simulated',
    color: 'blue',
    explanation:
      'Generated by a model or simulation. These values are not direct observations of an intervention outcome.',
  },
  third_party: {
    label: 'Third party',
    color: 'gray',
    explanation:
      'Supplied by an external data provider. Methods, resolution and limitations depend on that source.',
  },
}

export function DataSourceBadge({ source }: { source: unknown }): ReactNode {
  const known =
    typeof source === 'string' && Object.hasOwn(SOURCES, source) ? (source as DataSource) : null
  const item = known
    ? SOURCES[known]
    : {
        label: 'Source unavailable',
        color: 'gray',
        explanation:
          'The API has not supplied a recognized data source. No provenance is being assumed.',
      }
  return (
    <Tooltip
      label={item.explanation}
      withArrow
      multiline
      w={285}
      events={{ hover: true, focus: true, touch: true }}
    >
      <Badge
        variant="light"
        color={item.color}
        tabIndex={0}
        data-source={known ?? 'unknown'}
        aria-label={`Data source: ${item.label}`}
      >
        {item.label}
      </Badge>
    </Tooltip>
  )
}
